package com.marinainsaurralde.plango.data;
import com.marinainsaurralde.plango.model.*;import java.util.*;
public final class AgrupadorEventos {private AgrupadorEventos(){}public static List<GrupoUbicacion> agrupar(List<Evento> eventos){Map<Clave,List<Evento>>groups=new LinkedHashMap<>();if(eventos!=null)for(Evento e:eventos)if(e.hasValidCoordinates())groups.computeIfAbsent(new Clave(e.getLatitud(),e.getLongitud()),k->new ArrayList<>()).add(e);List<GrupoUbicacion>result=new ArrayList<>();groups.forEach((k,v)->result.add(new GrupoUbicacion(k.lat,k.lon,v)));return result;}private static final class Clave{final double lat,lon;Clave(double a,double o){lat=a;lon=o;}public boolean equals(Object x){if(!(x instanceof Clave))return false;Clave k=(Clave)x;return Double.doubleToLongBits(lat)==Double.doubleToLongBits(k.lat)&&Double.doubleToLongBits(lon)==Double.doubleToLongBits(k.lon);}public int hashCode(){return Objects.hash(Double.doubleToLongBits(lat),Double.doubleToLongBits(lon));}}}
